def num_comm_div(a, b):
    # Initialize the count of common divisors
    count = 0

    # Loop through all possible divisors up to the minimum of a and b
    for i in range(1, min(a, b) + 1):
        # If both a and b are divisible by i, then it is a common divisor
        if a % i == 0 and b % i == 0:
            count += 1

    return count

def count_element_freq(tup):
    freq = {}
    for item in tup:
        if isinstance(item, tuple):
            for sub_item in item:
                if sub_item in freq:
                    freq[sub_item] += 1
                else:
                    freq[sub_item] = 1
        else:
            if item in freq:
                freq[item] += 1
            else:
                freq[item] = 1
